import java.time.*;import java.util.*;
interface PricingRule {double fee(int minutes,LocalTime entry);}
abstract class Vehicle {final String reg;final PricingRule pricing;Vehicle(String r,PricingRule p){reg=r;pricing=p;}double fee(int mins,LocalTime in){return pricing.fee(mins,in);}}
class StandardRate implements PricingRule {final double rate;StandardRate(double r){rate=r;}public double fee(int m,LocalTime t){return ((m+59)/60)*rate;}}
class E_Bike extends Vehicle {E_Bike(String r){super(r,(m,t)->25.0);}}
class DeliveryVan extends Vehicle {DeliveryVan(String r){super(r,(m,t)->{double base=((m+59)/60)*30.0;return !t.isBefore(LocalTime.of(9,0))&&t.isBefore(LocalTime.of(17,0))?base*2:base;});}}
class CarV extends Vehicle {CarV(String r){super(r,new StandardRate(30));}}
class DayPass {final String holder;final LocalDate issueDate;DayPass(String h,LocalDate issued){holder=h;issueDate=issued;}boolean validFor(LocalDate date){return holder!=null&&!holder.isBlank()&&issueDate.equals(date);}}
class MultiFloorParking {final String[][] slots;MultiFloorParking(int[] capacities){slots=new String[capacities.length][];for(int i=0;i<capacities.length;i++)slots[i]=new String[capacities[i]];}int[] allocate(String reg){for(int f=0;f<slots.length;f++)for(int s=0;s<slots[f].length;s++)if(slots[f][s]==null){slots[f][s]=reg;return new int[]{f,s};}return null;}}
public class Task12 {public static void main(String[] a){int[] capacities={2,3,1,4,2};MultiFloorParking p=new MultiFloorParking(capacities);System.out.println("Floors="+capacities.length+", total slots="+Arrays.stream(capacities).sum());System.out.println("E-bike flat fee Rs "+new E_Bike("TN-E1").fee(125,LocalTime.NOON));System.out.println("Delivery van peak fee Rs "+new DeliveryVan("TN-V1").fee(60,LocalTime.of(10,0)));System.out.println("Delivery van off-peak fee Rs "+new DeliveryVan("TN-V2").fee(60,LocalTime.of(18,0)));System.out.println("Car fee Rs "+new CarV("TN-C1").fee(60,LocalTime.NOON));DayPass pass=new DayPass("VISITOR-01",LocalDate.now());System.out.println("Visitor one-day pass valid on issue date="+pass.validFor(LocalDate.now()));System.out.println("Visitor one-day pass valid next day="+pass.validFor(LocalDate.now().plusDays(1)));System.out.println("Allocated slot="+Arrays.toString(p.allocate("TN-E1")));System.out.println("Design decision: MODIFY; use pricing strategy + jagged array + pass abstraction");}}
